require('dotenv').config()
const { GoogleGenAI } = require('@google/genai')

async function test() {
  console.log('API Key length:', process.env.GEMINI_API_KEY ? process.env.GEMINI_API_KEY.length : 0)
  console.log('API Key starts with:', process.env.GEMINI_API_KEY ? process.env.GEMINI_API_KEY.substring(0, 10) : 'none')

  const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY })

  const modelsToTest = ['gemini-2.5-flash', 'gemini-1.5-flash', 'gemini-2.0-flash-exp']

  for (const model of modelsToTest) {
    try {
      console.log(`\nTesting model: ${model}...`)
      const response = await ai.models.generateContent({
        model: model,
        contents: 'Hello, respond with "OK" if you can hear me.'
      })
      console.log(`✅ Success for ${model}:`, response.text.trim())
      return // If one succeeds, we know it works!
    } catch (err) {
      console.error(`❌ Failed for ${model}:`, err.message || err)
    }
  }
}

test()
